// Code generated by '_gen'
package arm9

import (
	"fmt"
	"math"
	"math/bits"

	"github.com/aabalke/guac/emu/cpu/arm7"
)

// NOTE: order of decoders effects order checked and therefore implimentation
const (
	INST_BLX arm7.Decoder = iota
	INST_PLD
	INST_NV
	INST_SVC
	INST_BKP
	INST_CRT
	INST_BRA
	INST_BRX
	INST_SDT_REG
	INST_SDT_IMM
	INST_BLK
	INST_MUL
	INST_SWP
	INST_HAL
	INST_UND
	INST_MRS
	INST_MSR
	INST_HWM
	INST_CLZ
	INST_QAL
	INST_ALU
	INST_ALU_SHIFT_REG
	INST_ALU_SHIFT_IMM
)

// other coprocessor instructions are not necessary since cp15 is a control coprocessor not a data one
var formatters = []arm7.Formatter{
	INST_PLD:           {0xFD70_F000, 0xF550_F000},
	INST_BLX:           {0xFE00_0000, 0xFA00_0000},
	INST_NV:            {0xF000_0000, 0xF000_0000},
	INST_BKP:           {0xFFF0_00F0, 0xE120_0070},
	INST_SVC:           {0x0F00_0000, 0x0F00_0000},
	INST_BRA:           {0x0E00_0000, 0x0A00_0000},
	INST_BRX:           {0x0FFF_FF00, 0x012F_FF00},
	INST_UND:           {0x0E00_0010, 0x0600_0010},
	INST_MUL:           {0x0F00_00F0, 0x0000_0090},
	INST_HWM:           {0x0F90_0090, 0x0100_0080},
	INST_CLZ:           {0x0FFF_0FF0, 0x016F_0F10},
	INST_QAL:           {0x0F90_0FF0, 0x0100_0050},
	INST_SWP:           {0x0FB0_0FF0, 0x0100_0090},
	INST_BLK:           {0x0E00_0000, 0x0800_0000},
	INST_HAL:           {0x0E00_0090, 0x0000_0090},
	INST_SDT_REG:       {0x0E00_0010, 0x0600_0000},
	INST_SDT_IMM:       {0x0E00_0000, 0x0400_0000},
	INST_ALU:           {0x0E00_0000, 0x0200_0000},
	INST_ALU_SHIFT_REG: {0x0E00_0090, 0x0000_0010},
	INST_ALU_SHIFT_IMM: {0x0E00_0010, 0x0000_0000},
	INST_CRT:           {0x0F00_0010, 0x0E00_0010},
	INST_MRS:           {0x0FBF_0FFF, 0x010F_0000},
	INST_MSR:           {0x0DB0_F000, 0x0120_F000},
}

func (c *Cpu) DecodeArm(op uint32) {
	if cond := op >> 28; !c.Reg.CPSR.CheckCond(cond) {
		c.Seq = arm7.SEQ
		return
	}

	for decoder, desc := range formatters {

		if (op & desc.Mask) != desc.Match {
			continue
		}

		switch arm7.Decoder(decoder) {
		case INST_BLX:
			c.Blx(op)
		case INST_PLD:
			panic(fmt.Sprintf("arm9: unsetup pld instruction pc %08X op %08X\n", c.Reg.R[PC], op))
		case INST_SVC:
			c.Exception(arm7.VEC_SWI, arm7.MODE_SWI)
		case INST_BKP:
			c.Exception(arm7.VEC_PREFETCH, arm7.MODE_ABT)
		case INST_CRT:
			c.CoDataReg(op)
		case INST_BRA:
			c.Branch(op)
		case INST_BRX:
			c.BranchExchange(op)
		case INST_SDT_IMM, INST_SDT_REG:
			c.Sdt(op)
		case INST_BLK:
			c.Block(op)
		case INST_HAL:
			c.Half(op)
		case INST_UND:
			c.Exception(arm7.VEC_UNDEFINED, arm7.MODE_UND)
		case INST_MRS:
			c.Mrs(op)
		case INST_MSR:
			c.Msr(op)
		case INST_SWP:
			c.Swp(op)
		case INST_MUL:
			c.Mul(op)
		case INST_CLZ:
			c.Clz(op)
		case INST_QAL:
			c.Qalu(op)
		case INST_HWM:
			c.ExtendedMul(op)
		case INST_ALU, INST_ALU_SHIFT_IMM, INST_ALU_SHIFT_REG:
			c.Alu(op)
		case INST_NV:
			c.Seq = arm7.SEQ
			return
		}
		return
	}

	panic(fmt.Sprintf("arm9: decode failed pc %08X op %08X\n", c.Reg.R[PC], op))
}

const (
	SMLAxy = iota
	SMLAWySMLALWy
	SMLALxy
	SMULxy
)

// TODO: need to add proper idle and timings for all multiplications

func (c *Cpu) ExtendedMul(op uint32) {
	var (
		r   = &c.Reg.R
		rd  = (op >> 16) & 0xF
		rn  = (op >> 12) & 0xF
		rs  = (op >> 8) & 0xF
		rm  = (op >> 0) & 0xF
		x   = (op >> 5) & 1
		y   = (op >> 6) & 1
		rsV = int64(int16(uint16(r[rs] >> (16 * y))))
	)

	switch inst := (op >> 21) & 3; inst {
	case SMLAxy, SMULxy:
		rmV := int64(int16(uint16(r[rm] >> (16 * x))))
		res := (rmV * rsV)

		if inst == SMLAxy {
			res += int64(int32(r[rn]))
			if res > math.MaxInt32 || res < math.MinInt32 {
				c.Reg.CPSR.Q = true
			}
		}

		r[rd] = uint32(res)

	case SMLAWySMLALWy:
		rmV := int64(int32(r[rm]))
		res := (rmV * rsV) >> 16

		if smulwa := x == 0; smulwa {
			res += int64(int32(r[rn]))
			if res > math.MaxInt32 || res < math.MinInt32 {
				c.Reg.CPSR.Q = true
			}
		}

		r[rd] = uint32(res)

	case SMLALxy:
		rmV := int64(int16(uint16(r[rm] >> (16 * x))))
		res := (rsV * rmV) + (int64(int32(r[rd]))<<32 | int64(int32(r[rn])))
		r[rn] = uint32(res)
		r[rd] = uint32(res >> 32)
	}
}

func (c *Cpu) Blx(op uint32) {
	r := &c.Reg.R
	r[LR] = r[PC] - 4
	r[PC] += uint32((int32(op) << 8) >> 6)
	r[PC] += ((op >> 24) & 1) << 1

	c.Reg.CPSR.T = true
	c.Reload = true
}

func (c *Cpu) BranchExchange(op uint32) {
	var (
		r  = &c.Reg.R
		rn = op & 0xF
	)

	switch inst := (op >> 4) & 0xF; inst {
	case arm7.INST_BX:
		r[PC] = r[rn]
	case arm7.INST_BXJ:
		panic("unsupported bxj instruction")
	case arm7.INST_BLX:

		if rn == LR {
			// Using BLX R14 is possible (sets PC=Old_LR, and New_LR=retadr).
			tmp := r[LR]
			r[LR] = r[PC] - 4
			r[PC] = tmp
		} else {
			r[LR] = r[PC] - 4
			r[PC] = r[rn]
		}
	}

	c.ToggleThumb()
}

func (c *Cpu) Half(op uint32) {
	var (
		r       = &c.Reg.R
		rn      = (op >> 16) & 0xF
		rd      = (op >> 12) & 0xF
		preFlag = (op>>24)&1 != 0
		inst    = (op >> 5) & 3
		wb      = (op>>21)&1 != 0 || !preFlag
		rnv     = r[rn]
		post    = rnv
	)

	var offset uint32
	if imm := (op>>22)&1 != 0; imm {
		offset = (op & 0xF) | ((op >> 4) & 0xF0)
	} else {
		offset = r[op&0xF]
	}

	if up := (op>>23)&1 != 0; up {
		post += offset
	} else {
		post -= offset
	}

	var addr uint32
	if preFlag {
		addr = post
	} else {
		addr = rnv
	}

	if load := (op>>20)&1 != 0; !load {
		rdv := r[rd]

		var rd2v uint32
		if inst == arm7.STRD {
			rd2v = r[rd+1]
		}

		if wb {
			r[rn] = post
		}

		switch inst {
		case arm7.STRH:
			c.Write16(addr, uint16(rdv))

		case arm7.LDRD:
			addr &^= 7
			r[rd+0] = c.Read32(addr + 0)
			r[rd+1] = c.Read32(addr + 4)
		case arm7.STRD:
			addr &^= 7
			c.Write32(addr+0, rdv)
			c.Write32(addr+4, rd2v)
		default:
			panic("unsupported half store reserved")
		}

		return
	}

	if wb {
		r[rn] = post
	}

	switch inst {
	case arm7.LDRH:
		r[rd] = c.Read16(addr)
	case arm7.LDRSB:
		r[rd] = uint32(int32(int8(c.Read8(addr))))
	case arm7.LDRSH:
		r[rd] = uint32(int32(int16(c.Read16(addr))))
	default:
		panic("unsupported half load reserved")
	}
}

const (
	QADD  = 0
	QSUB  = 2
	QDADD = 4
	QDSUB = 6
)

func (c *Cpu) Qalu(op uint32) {
	var (
		r   = &c.Reg.R
		rnV = int64(int32(r[(op>>16)&0xF]))
		rmV = int64(int32(r[op&0xF]))
	)

	if double := op&(1<<22) != 0; double {

		rnV *= 2

		switch {
		case rnV > math.MaxInt32:
			c.Reg.CPSR.Q = true
			rnV = math.MaxInt32
		case rnV < math.MinInt32:
			c.Reg.CPSR.Q = true
			rnV = math.MinInt32
		}
	}

	if sub := op&(1<<21) != 0; sub {
		rnV = rmV - rnV
	} else {
		rnV += rmV
	}

	switch {
	case rnV > math.MaxInt32:
		c.Reg.CPSR.Q = true
		rnV = math.MaxInt32
	case rnV < math.MinInt32:
		c.Reg.CPSR.Q = true
		rnV = math.MinInt32
	}

	rd := (op >> 12) & 0xF
	r[rd] = uint32(rnV)
}

func (c *Cpu) Clz(op uint32) {
	c.Reg.R[(op>>12)&0xF] = uint32(bits.LeadingZeros32(c.Reg.R[op&0xF]))
}

func (c *Cpu) CoDataReg(op uint32) {
	var (
		r  = &c.Reg.R
		cn = (op >> 16) & 0xF
		cp = (op >> 5) & 7
		cm = (op >> 0) & 0xF
		rd = (op >> 12) & 0xF
	)

	if (op >> 28) == 0xF {
		panic("MRC2/MCR2")
	}

	if processor := uint8((op >> 8) & 0xF); processor != 15 {
		panic("co data register with pn != cp15")
	}

	if cpopc := (op >> 21) & 7; cpopc != 0 {
		panic("co data register with cpopc != 0")
	}

	idx := (cn << 8) | (cm << 4) | cp

	if mrc := (op>>20)&1 != 0; mrc {
		r[rd] = c.Cp15.Read(idx)
		c.Idle(3) // matches melondds
		return
	}

	c.Cp15.Write(idx, r[rd])
	c.Idle(2) // matches melondds
}

func (c *Cpu) Block(op uint32) {
	var (
		r     = &c.Reg.R
		rlist = op & 0xFFFF
		rn    = (op >> 16) & 0xF
		up    = (op>>23)&1 != 0
	)

	if rlist == 0 {
		if up {
			r[rn] += 0x40
		} else {
			r[rn] -= 0x40
		}
		return
	}

	var (
		pre        = (op>>24)&1 != 0
		psr        = (op>>22)&1 != 0
		wb         = (op>>21)&1 != 0
		load       = (op>>20)&1 != 0
		pcIncluded = rlist&0x8000 != 0
		rnIncluded = (rlist>>rn)&1 != 0
		regCount   = uint32(bits.OnesCount32(rlist))
		bytes      = regCount * 4
		first      = bits.TrailingZeros32(rlist)
		last       = bits.Len32(rlist) - 1
		isOnly     = regCount == 1
		isLast     = uint32(last) == rn
		addr       = r[rn]
	)

	mode := c.Reg.CPSR.Mode
	forceUser := psr && (mode != arm7.MODE_USR && mode != arm7.MODE_SYS) && (!load || !pcIncluded)
	if forceUser {
		c.ModeSwitch(mode, arm7.MODE_USR)
	}

	rnNew := addr
	if up {
		rnNew += bytes
	} else {
		pre = !pre
		rnNew -= bytes
		addr -= bytes
	}

	seq := uint32(arm7.NONSEQ)
	for i := first; i < 0x10; i++ {
		if disabled := rlist&(1<<i) == 0; disabled {
			continue
		}
		if pre {
			addr += 4
		}
		if load {
			r[i] = c.Read32Block(addr, seq)
		} else {
			c.Write32Block(addr, r[i], seq)
		}
		if !pre {
			addr += 4
		}
		seq = arm7.SEQ
	}

	if forceUser {
		c.ModeSwitch(arm7.MODE_USR, mode)
	}

	if wb {
		if load && rnIncluded {
			if isOnly || !isLast {
				r[rn] = rnNew
			}
		} else {
			r[rn] = rnNew
		}
	}

	if !load {
		return
	}

	//c.Idle(1) // gba has, not sure if arm9

	if !pcIncluded {
		return
	}

	c.Reload = true

	if !psr {
		// required for pop {pc}
		c.ToggleThumb()
		return
	}

	c.DoLdmLoadSwitch()
}
